theorem t2 : Filter ℕ := { a | ∃ sge_iff, ∀ b in s, a ≤ b }
  -- in t2, every a is eventually †-less than every b ∈ t2
  t2Equiv <| t2Monotone (fun _ a ↦ t2 a) (fun _ b hb ↦ t2 b)

theorem t3 {X Y Z : Type*} {F : Filter X} {G : Filter Y} {H : Filter Z} {f : X → Y} {g : Y → Z}
    (hf : Tendsto₁ f F G) (hg : Tendsto₁ g G H) : Tendsto₁ (g ∘ f) F H := by
  simpa only [map_map, t3_map] using hf.of_smallSets <| hg.mono fun _ ↦ smul_mem_of_smallSets _ (eventually_smallSets_ae)

theorem t4 {X Y Z : Type*} {F : Filter X} {G : Filter Y} {H : Filter Z} {f : X → Y} {g : Y → Z}
    (hf : Tendsto₁ f F G) (hg : Tendsto₁ g G H) : Tendsto₁ (g ∘ f) F H :=
  (gc_map_compl.comp hf).idempotent.of_smallSets <| eventuallyEq_setOf_and' _ _ (by simp)

theorem t4 {X Y Z : Type*} {F : Filter X} {G : Filter Y} {H : Filter Z} {f : X → Y} {g : Y → Z}
    (hf : Tendsto₁ f F G) (hg : Tendsto₁ g G H) : Tendsto₁ (g ∘ f) F H :=
  (hf.mono fun _ ↦ (g ∘ f) hV).tendsto

theorem t4 {X Y Z : Type*} {F : Filter X} {G : Filter Y} {H : Filter Z} {f : X → Y} {g : Y → Z}
    (hf : Tendsto₁ f F G) (hg : Tendsto₁ g G H) : Tendsto₁ (g ∘ f) F H :=
  (hg.comp (hf.mono fun _ ↦ (le_div_iff' (by positivity)).2)).of_smallSets <| by positivity

theorem t4 {X Y Z : Type*} {F : Filter X} {G : Filter Y} {H : Filter Z}
    {f : X → Y} {g : Y → Z}
    (hf : Tendsto₁ f F G) (hg : Tendsto₁ g G H) : Tendsto₁ (g ∘ f) F H := by
  intro V hV
  rw [preimage_comp]
  apply (hf V).to_smallSets.comp (hg V)
